import React, { useState } from "react";
import { useParams } from "react-router-dom";
import styled, { keyframes } from "styled-components";
import SyntaxHighlighter from "react-syntax-highlighter";
import { tomorrowNight } from "react-syntax-highlighter/dist/esm/styles/hljs";
import { FiCopy, FiDownload, FiCheck } from "react-icons/fi";
import program1 from "../programs/program1";
import program2 from "../programs/program2";
import program3 from "../programs/program3";
import program4 from "../programs/program4";
import program5 from "../programs/program5";
import program6 from "../programs/program6";
import program7 from "../programs/program7";
import program8 from "../programs/program8";
import program9 from "../programs/program9";
import program11 from "../programs/program11";

import program14 from "../programs/program14";
import program15 from "../programs/program15";
import program16 from "../programs/program16";

// Store all programs in an object for easy access by ID
const allPrograms = {
  1: program1,
  2: program2,
  3: program3,
  4: program4,
  5: program5,
  6: program6,
  7: program7,
  8: program8,
  9: program9,
  11: program11,
  14: program14,
  15: program15,
  16: program16
};

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
`;

const scaleUp = keyframes`
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
`;

const Container = styled.div`
  max-width: 900px;
  margin: 60px auto;
  padding: 0 20px;
  animation: ${fadeIn} 0.5s ease;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
`;

const Title = styled.h1`
  color: #f5f5f7;
  font-weight: 600;
  font-size: 2rem;
  margin-bottom: 24px;
  letter-spacing: -0.5px;
`;

const Toolbar = styled.div`
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
`;

const Button = styled.button`
  background: rgba(255, 255, 255, 0.08);
  color: #f5f5f7;
  border: none;
  padding: 10px 16px;
  border-radius: 14px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.3s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.15);
    transform: translateY(-2px) scale(1.02);
  }

  &:active {
    transform: scale(0.97);
  }
`;

const CodeWrapper = styled.div`
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  animation: ${scaleUp} 0.4s ease;
`;

const ModalOverlay = styled.div`
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Modal = styled.div`
  background: #242424;
  padding: 16px 24px;
  border-radius: 14px;
  color: #f5f5f7;
  font-weight: 500;
  font-size: 0.95rem;
  display: flex;
  align-items: center;
  gap: 10px;
  animation: ${scaleUp} 0.25s ease;
  box-shadow: 0 8px 30px rgba(0,0,0,0.4);
`;

export default function ProgramPage() {
  const { id } = useParams();
  const prog = programs[`program${id}`];
  const [showModal, setShowModal] = useState(null);

  if (!prog) return <p style={{ color: "#aaa", textAlign: "center", marginTop: "40px" }}>Program not found.</p>;

  const copyCode = () => {
    navigator.clipboard.writeText(prog.code);
    setShowModal("copied");
    setTimeout(() => setShowModal(null), 1800);
  };

  const downloadFile = () => {
    const blob = new Blob([prog.code], { type: "text/plain;charset=utf-8" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `program${prog.id}.c`;
    link.click();
    setShowModal("downloaded");
    setTimeout(() => setShowModal(null), 1800);
  };

  return (
    <Container>
      <Title>{prog.title}</Title>

      <Toolbar>
        <Button onClick={copyCode}><FiCopy /> Copy</Button>
        <Button onClick={downloadFile}><FiDownload /> Download</Button>
      </Toolbar>

      <CodeWrapper>
        <SyntaxHighlighter
          language={prog.lang}
          style={tomorrowNight}
          showLineNumbers
          wrapLongLines
          customStyle={{ margin: 0, padding: "24px", background: "#1c1c1e" }}
        >
          {prog.code}
        </SyntaxHighlighter>
      </CodeWrapper>

      {showModal && (
        <ModalOverlay>
          <Modal>
            <FiCheck /> {showModal === "copied" ? "Copied to clipboard!" : "File downloaded!"}
          </Modal>
        </ModalOverlay>
      )}
    </Container>
  );
}
